//! Rust port of TPTBox.core.internal.nii_help.affine_resample (TPTBox/core/internal/nii_help.py), generated by fast-anything.
//! Check it with:  fast-anything verify TPTBox.core.internal.nii_help.affine_resample
//!
//! Reproduces `scipy.ndimage.affine_transform` (scipy 1.17) for order 0/1 and modes nearest/constant bit for bit:
//! - input coordinate of output voxel `o` on axis h: `t = offset[h]; t += o_0 * m[h][0]; t += o_1 * m[h][1]; ...`
//! - mode "constant": a coordinate outside `[0, n - 1]` (or NaN) on any axis gives `cval`; inside, a tap past the
//!   end is mirrored (`n -> n - 2`). Mode "nearest" never clamps the coordinate, only the tap indices.
//! - `start = (npy_intp)floor(c)` (order 1) or `floor(c + 0.5)` (order 0), with x86 semantics: out of range or
//!   NaN gives INT64_MIN. Order-1 weights: `x = c - floor(c)`, `w0 = 1 - x`, `w1 = 1 - w0`.
//! - value: `t = 0; for each tap (C order): coeff = v; coeff *= w_axis0; ...; t += coeff`.
//! - output: float casts; integers rounded half away from zero, clamped, then cast like the C code on x86-64.
//!
//! One deliberate difference: an empty `arr` with mode "nearest" raises ValueError. scipy reads memory outside
//! the array there, so its result is not deterministic.

use numpy::ndarray::IxDyn;
use numpy::{Element, PyArrayDyn, PyArrayMethods, PyReadonlyArrayDyn, PyUntypedArray, PyUntypedArrayMethods};
use pyo3::exceptions::{PyTypeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::PyTuple;

const DTYPES: [&str; 10] = ["uint8", "uint16", "uint32", "uint64", "int8", "int16", "int32", "int64", "float32", "float64"];
const TWO63: f64 = 9223372036854775808.0;

/// C `(npy_intp)x` on x86-64 (cvttsd2si): out of range and NaN give INT64_MIN.
#[inline(always)]
fn intp(x: f64) -> i64 {
    if x >= -TWO63 && x < TWO63 { x as i64 } else { i64::MIN }
}

/// C `(int)x` on x86-64: out of range and NaN give INT32_MIN.
#[inline(always)]
fn int32(x: f64) -> i32 {
    if x >= -2147483648.0 && x < 2147483648.0 { x as i32 } else { i32::MIN }
}

#[inline(always)]
fn round_signed(t: f64) -> f64 {
    if t > 0.0 { t + 0.5 } else { t - 0.5 }
}

#[inline(always)]
fn round_unsigned(t: f64) -> f64 {
    if t > 0.0 { t + 0.5 } else { 0.0 }
}

trait In: Copy {
    /// The element at `p` (possibly unaligned) as a double.
    unsafe fn get(p: *const u8) -> f64;
}

macro_rules! impl_in {
    ($($t:ty),*) => {$(
        impl In for $t {
            #[inline(always)]
            unsafe fn get(p: *const u8) -> f64 {
                unsafe { std::ptr::read_unaligned(p as *const $t) as f64 }
            }
        }
    )*};
}
impl_in!(u8, u16, u32, u64, i8, i16, i32, i64, f32, f64);

trait Out: Element + Copy + Send {
    fn conv(t: f64) -> Self;
}

impl Out for f64 {
    #[inline(always)]
    fn conv(t: f64) -> Self {
        t
    }
}
impl Out for f32 {
    #[inline(always)]
    fn conv(t: f64) -> Self {
        t as f32
    }
}

macro_rules! impl_out_small_signed {
    ($($t:ty),*) => {$(
        impl Out for $t {
            #[inline(always)]
            fn conv(t: f64) -> Self {
                let u = round_signed(t);
                if u > <$t>::MAX as f64 {
                    <$t>::MAX
                } else if u < <$t>::MIN as f64 {
                    <$t>::MIN
                } else {
                    int32(u) as $t // truncation of the 32-bit conversion, as C does: NaN -> 0 for 8/16 bit
                }
            }
        }
    )*};
}
impl_out_small_signed!(i8, i16, i32);

impl Out for i64 {
    #[inline(always)]
    fn conv(t: f64) -> Self {
        let u = round_signed(t);
        if u > i64::MAX as f64 {
            i64::MAX
        } else if u < i64::MIN as f64 {
            i64::MIN
        } else {
            intp(u)
        }
    }
}

macro_rules! impl_out_small_unsigned {
    ($($t:ty),*) => {$(
        impl Out for $t {
            #[inline(always)]
            fn conv(t: f64) -> Self {
                let u = round_unsigned(t);
                if u > <$t>::MAX as f64 { <$t>::MAX } else { u as $t }
            }
        }
    )*};
}
impl_out_small_unsigned!(u8, u16, u32);

impl Out for u64 {
    #[inline(always)]
    fn conv(t: f64) -> Self {
        // GCC's double -> uint64 on x86-64; values from 2^64 up (and inf) come out as 0, as in scipy.
        let u = round_unsigned(t);
        if u < TWO63 { intp(u) as u64 } else { (intp(u - TWO63) as u64) ^ (1u64 << 63) }
    }
}

/// Tap index past the image edge: clamped for "nearest", mirrored for "constant".
#[inline(always)]
fn map_tap(idx: i64, n: i64, constant: bool) -> i64 {
    if idx >= 0 && idx < n {
        return idx;
    }
    if !constant {
        return if idx < 0 { 0 } else { n - 1 };
    }
    if n <= 1 {
        return 0;
    }
    let s2 = 2 * n - 2;
    if idx < 0 {
        let i = s2 * (-idx / s2) + idx;
        if i <= 1 - n { i + s2 } else { -i }
    } else {
        let i = idx - s2 * (idx / s2);
        if i >= n { s2 - i } else { i }
    }
}

/// One input axis of one output voxel: in range (constant mode), byte offsets of the taps, weights.
#[derive(Clone, Copy, Default)]
struct Tap {
    ok: bool,
    i0: isize,
    i1: isize,
    w0: f64,
    w1: f64,
}

#[inline(always)]
fn make_tap(c: f64, n: i64, stride: isize, order1: bool, constant: bool) -> Tap {
    if constant && !(c >= 0.0 && c <= (n - 1) as f64) {
        return Tap::default();
    }
    if !order1 {
        let s = intp((c + 0.5).floor());
        Tap { ok: true, i0: map_tap(s, n, constant) as isize * stride, i1: 0, w0: 1.0, w1: 0.0 }
    } else {
        let fl = c.floor();
        let x = c - fl;
        let w0 = 1.0 - x;
        let w1 = 1.0 - w0;
        let s = intp(fl);
        Tap {
            ok: true,
            i0: map_tap(s, n, constant) as isize * stride,
            i1: map_tap(s.wrapping_add(1), n, constant) as isize * stride,
            w0,
            w1,
        }
    }
}

#[inline(always)]
unsafe fn eval<I: In>(src: *const u8, taps: &[Tap], order1: bool) -> f64 {
    let r = taps.len();
    if !order1 {
        let mut o = 0isize;
        for t in taps {
            o += t.i0;
        }
        return 0.0 + unsafe { I::get(src.offset(o)) };
    }
    let mut acc = 0.0f64;
    for k in 0..(1u64 << r) {
        let mut o = 0isize;
        for (h, t) in taps.iter().enumerate() {
            o += if (k >> (r - 1 - h)) & 1 == 0 { t.i0 } else { t.i1 };
        }
        let mut coeff = unsafe { I::get(src.offset(o)) };
        for (h, t) in taps.iter().enumerate() {
            coeff *= if (k >> (r - 1 - h)) & 1 == 0 { t.w0 } else { t.w1 };
        }
        acc += coeff;
    }
    acc
}

struct SendPtr(*const u8);
unsafe impl Send for SendPtr {}
unsafe impl Sync for SendPtr {}

struct Job {
    src: SendPtr,
    in_shape: Vec<i64>,
    in_strides: Vec<isize>,
    out_shape: Vec<usize>,
    m: Vec<f64>, // row-major, input axis h by output axis j
    off: Vec<f64>,
    order1: bool,
    constant: bool,
    cval: f64,
}

/// Calls `f(prefix, row_start)` for every output row (all axes but the last fixed), in C order.
fn for_each_row(out_shape: &[usize], mut f: impl FnMut(&[usize], usize)) {
    let r = out_shape.len();
    let last = out_shape[r - 1];
    let rows: usize = out_shape[..r - 1].iter().product();
    let mut idx = vec![0usize; r - 1];
    for row in 0..rows {
        f(&idx, row * last);
        for d in (0..r - 1).rev() {
            idx[d] += 1;
            if idx[d] < out_shape[d] {
                break;
            }
            idx[d] = 0;
        }
    }
}

/// Which output axis each input axis reads, when every matrix row has at most one non-zero entry (a scaling,
/// flip or axis permutation). Terms with a zero entry are +-0 for every output index, so coordinates computed
/// from that one axis are bit-identical to the full sum.
fn columns(m: &[f64], r: usize) -> Option<Vec<usize>> {
    (0..r)
        .map(|h| {
            let nz: Vec<usize> = (0..r).filter(|&j| m[h * r + j] != 0.0 || m[h * r + j].is_nan()).collect();
            match nz.len() {
                0 => Some(0),
                1 => Some(nz[0]),
                _ => None,
            }
        })
        .collect()
}

/// Tap table of input axis `h` over the output axis `p` it reads, with the other output indices at 0.
fn tap_table(job: &Job, h: usize, p: usize) -> Vec<Tap> {
    let r = job.out_shape.len();
    (0..job.out_shape[p])
        .map(|q| {
            let mut t = job.off[h];
            for j in 0..r {
                let o = if j == p { q as f64 } else { 0.0 };
                t += o * job.m[h * r + j];
            }
            make_tap(t, job.in_shape[h], job.in_strides[h], job.order1, job.constant)
        })
        .collect()
}

#[inline(always)]
unsafe fn eval3<I: In>(src: *const u8, a: Tap, b: Tap, c: Tap) -> f64 {
    let mut acc = 0.0f64;
    for (ia, wa) in [(a.i0, a.w0), (a.i1, a.w1)] {
        for (ib, wb) in [(b.i0, b.w0), (b.i1, b.w1)] {
            for (ic, wc) in [(c.i0, c.w0), (c.i1, c.w1)] {
                let mut coeff = unsafe { I::get(src.offset(ia + ib + ic)) };
                coeff *= wa;
                coeff *= wb;
                coeff *= wc;
                acc += coeff;
            }
        }
    }
    acc
}

/// 3D, with the order and the mode fixed at compile time.
fn compute3<I: In, O: Out, const ORDER1: bool, const CONSTANT: bool>(job: &Job, out: &mut [O]) {
    let src = job.src.0;
    let cval = O::conv(job.cval);
    let [d0, d1, d2] = [job.out_shape[0], job.out_shape[1], job.out_shape[2]];
    if let Some(col) = columns(&job.m, 3) {
        let tables: Vec<Vec<Tap>> = (0..3).map(|h| tap_table(job, h, col[h])).collect();
        if !ORDER1 {
            // one gather per voxel: offsets and range flags summed per output axis
            let mut comb: Vec<Vec<(bool, isize)>> = job.out_shape.iter().map(|&d| vec![(true, 0isize); d]).collect();
            for h in 0..3 {
                for (q, t) in tables[h].iter().enumerate() {
                    comb[col[h]][q].0 &= t.ok;
                    comb[col[h]][q].1 += t.i0;
                }
            }
            let mut start = 0;
            for o0 in 0..d0 {
                let (ok0, off0) = comb[0][o0];
                for o1 in 0..d1 {
                    let (ok1, off1) = comb[1][o1];
                    let base = off0 + off1;
                    let ok01 = ok0 && ok1;
                    let row = &mut out[start..start + d2];
                    for (o, &(ok2, off2)) in row.iter_mut().zip(&comb[2]) {
                        *o = if CONSTANT && !(ok01 && ok2) {
                            cval
                        } else {
                            O::conv(0.0 + unsafe { I::get(src.offset(base + off2)) })
                        };
                    }
                    start += d2;
                }
            }
        } else {
            let mut start = 0;
            let mut taps = [Tap::default(); 3];
            for o0 in 0..d0 {
                for o1 in 0..d1 {
                    for h in 0..3 {
                        if col[h] == 0 {
                            taps[h] = tables[h][o0];
                        } else if col[h] == 1 {
                            taps[h] = tables[h][o1];
                        }
                    }
                    let row = &mut out[start..start + d2];
                    for (q, o) in row.iter_mut().enumerate() {
                        for h in 0..3 {
                            if col[h] == 2 {
                                taps[h] = tables[h][q];
                            }
                        }
                        let [a, b, c] = taps;
                        *o = if CONSTANT && !(a.ok && b.ok && c.ok) { cval } else { O::conv(unsafe { eval3::<I>(src, a, b, c) }) };
                    }
                    start += d2;
                }
            }
        }
        return;
    }
    // General matrix: t = offset; t += o0 * m0; t += o1 * m1 once per row, then t += o2 * m2 per voxel.
    // An input axis whose last-column entry is zero has the same taps along a whole row (kind 0), and one whose
    // first two entries are zero reads a table over the last axis (kind 1); o * (+-0) is the same signed zero for
    // every o >= 0, so both are bit-identical to the full sum.
    let m = &job.m;
    let zero = |x: f64| x == 0.0;
    // kind 0: constant along a row, 1: table over the last output axis, 2: computed per voxel
    let kind: [u8; 3] = std::array::from_fn(|h| {
        if zero(m[h * 3 + 2]) {
            0
        } else if zero(m[h * 3]) && zero(m[h * 3 + 1]) {
            1
        } else {
            2
        }
    });
    let tables: [Vec<Tap>; 3] = std::array::from_fn(|h| if kind[h] == 1 { tap_table(job, h, 2) } else { Vec::new() });
    let n = [job.in_shape[0], job.in_shape[1], job.in_shape[2]];
    let st = [job.in_strides[0], job.in_strides[1], job.in_strides[2]];
    let m2 = [m[2], m[5], m[8]];
    let mut start = 0;
    for o0 in 0..d0 {
        for o1 in 0..d1 {
            let base: [f64; 3] = std::array::from_fn(|h| {
                let mut t = job.off[h];
                t += o0 as f64 * m[h * 3];
                t += o1 as f64 * m[h * 3 + 1];
                t
            });
            let rt: [Tap; 3] = std::array::from_fn(|h| {
                if kind[h] == 0 { make_tap(base[h] + 0.0 * m2[h], n[h], st[h], ORDER1, CONSTANT) } else { Tap::default() }
            });
            let pick = |h: usize, q: usize| -> Tap {
                match kind[h] {
                    0 => rt[h],
                    1 => tables[h][q],
                    _ => make_tap(base[h] + q as f64 * m2[h], n[h], st[h], ORDER1, CONSTANT),
                }
            };
            let row = &mut out[start..start + d2];
            for (q, o) in row.iter_mut().enumerate() {
                let (a, b, c) = (pick(0, q), pick(1, q), pick(2, q));
                *o = if CONSTANT && !(a.ok && b.ok && c.ok) {
                    cval
                } else if ORDER1 {
                    O::conv(unsafe { eval3::<I>(src, a, b, c) })
                } else {
                    O::conv(0.0 + unsafe { I::get(src.offset(a.i0 + b.i0 + c.i0)) })
                };
            }
            start += d2;
        }
    }
}

fn compute<I: In, O: Out>(job: &Job, out: &mut [O]) {
    let r = job.out_shape.len();
    if out.is_empty() {
        return;
    }
    if r == 3 {
        match (job.order1, job.constant) {
            (false, false) => compute3::<I, O, false, false>(job, out),
            (false, true) => compute3::<I, O, false, true>(job, out),
            (true, false) => compute3::<I, O, true, false>(job, out),
            (true, true) => compute3::<I, O, true, true>(job, out),
        }
        return;
    }
    let src = job.src.0;
    let cval = O::conv(job.cval);
    let last = job.out_shape[r - 1];
    let mut taps = vec![Tap::default(); r];

    if let Some(column) = columns(&job.m, r) {
        let tables: Vec<Vec<Tap>> = (0..r).map(|h| tap_table(job, h, column[h])).collect();
        let varying: Vec<usize> = (0..r).filter(|&h| column[h] == r - 1).collect();
        for_each_row(&job.out_shape, |prefix, start| {
            for h in 0..r {
                if column[h] != r - 1 {
                    taps[h] = tables[h][prefix[column[h]]];
                }
            }
            let row = &mut out[start..start + last];
            for (q, o) in row.iter_mut().enumerate() {
                for &h in &varying {
                    taps[h] = tables[h][q];
                }
                *o = if job.constant && !taps.iter().all(|t| t.ok) {
                    cval
                } else {
                    O::conv(unsafe { eval::<I>(src, &taps, job.order1) })
                };
            }
        });
        return;
    }

    // General matrix: per row, the sum over all but the last output axis, then one more term per voxel.
    let mut base = vec![0.0f64; r];
    for_each_row(&job.out_shape, |prefix, start| {
        for h in 0..r {
            let mut t = job.off[h];
            for (j, &o) in prefix.iter().enumerate() {
                t += o as f64 * job.m[h * r + j];
            }
            base[h] = t;
        }
        let row = &mut out[start..start + last];
        for (q, o) in row.iter_mut().enumerate() {
            let mut ok = true;
            for h in 0..r {
                let c = base[h] + q as f64 * job.m[h * r + r - 1];
                taps[h] = make_tap(c, job.in_shape[h], job.in_strides[h], job.order1, job.constant);
                ok &= taps[h].ok;
            }
            *o = if !ok { cval } else { O::conv(unsafe { eval::<I>(src, &taps, job.order1) }) };
        }
    });
}

fn run<'py, I: In, O: Out>(py: Python<'py>, job: Job) -> PyResult<Bound<'py, PyAny>> {
    let out = unsafe { PyArrayDyn::<O>::new(py, IxDyn(&job.out_shape), false) };
    {
        let slice = unsafe { out.as_slice_mut() }.map_err(|e| PyValueError::new_err(e.to_string()))?;
        py.detach(|| compute::<I, O>(&job, slice));
    }
    Ok(out.into_any())
}

macro_rules! dispatch_out {
    ($py:expr, $job:expr, $i:ty, $out:expr) => {
        match $out {
            "uint8" => run::<$i, u8>($py, $job),
            "uint16" => run::<$i, u16>($py, $job),
            "uint32" => run::<$i, u32>($py, $job),
            "uint64" => run::<$i, u64>($py, $job),
            "int8" => run::<$i, i8>($py, $job),
            "int16" => run::<$i, i16>($py, $job),
            "int32" => run::<$i, i32>($py, $job),
            "int64" => run::<$i, i64>($py, $job),
            "float32" => run::<$i, f32>($py, $job),
            _ => run::<$i, f64>($py, $job),
        }
    };
}

#[pyfunction]
#[allow(clippy::too_many_arguments)]
fn affine_resample<'py>(
    py: Python<'py>,
    arr: &Bound<'py, PyAny>,
    matrix: &Bound<'py, PyAny>,
    offset: &Bound<'py, PyAny>,
    output_shape: &Bound<'py, PyAny>,
    order: &Bound<'py, PyAny>,
    mode: &Bound<'py, PyAny>,
    cval: &Bound<'py, PyAny>,
    output_dtype: &Bound<'py, PyAny>,
) -> PyResult<Bound<'py, PyAny>> {
    // The checks of the Python function, in its order and with its exception types.
    if !PyTuple::new(py, [0i64, 1])?.contains(order)? {
        return Err(PyValueError::new_err(format!("order must be 0 or 1, got {}", order.repr()?)));
    }
    if !PyTuple::new(py, ["nearest", "constant"])?.contains(mode)? {
        return Err(PyValueError::new_err(format!("mode must be 'nearest' or 'constant', got {}", mode.repr()?)));
    }
    let dtypes = PyTuple::new(py, DTYPES)?;
    let in_dtype = arr.getattr("dtype")?;
    let in_name = in_dtype.getattr("name")?;
    if !dtypes.contains(&in_name)? || (!output_dtype.is_none() && !dtypes.contains(output_dtype)?) {
        return Err(PyTypeError::new_err(format!("unsupported dtypes {} -> {}", in_dtype.str()?, output_dtype.str()?)));
    }
    let np = py.import("numpy")?;
    let float64 = np.getattr("float64")?;
    if matrix.getattr("dtype")?.ne(&float64)? || offset.getattr("dtype")?.ne(&float64)? {
        return Err(PyTypeError::new_err("matrix and offset must be float64"));
    }
    let n: usize = arr.getattr("ndim")?.extract()?;
    if n == 0
        || matrix.getattr("shape")?.ne(PyTuple::new(py, [n, n])?)?
        || offset.getattr("shape")?.ne(PyTuple::new(py, [n])?)?
        || output_shape.len()? != n
    {
        return Err(PyValueError::new_err(format!(
            "shapes do not fit a {n}D image: matrix {}, offset {}, output {}",
            matrix.getattr("shape")?.str()?,
            offset.getattr("shape")?.str()?,
            output_shape.str()?
        )));
    }
    let mode: String = mode.extract()?;
    let constant = mode == "constant";
    let size: usize = arr.getattr("size")?.extract()?;
    if size == 0 && !constant {
        return Err(PyValueError::new_err("mode='nearest' needs a non-empty image"));
    }
    let mut out_shape = Vec::with_capacity(n);
    for v in output_shape.try_iter()? {
        let v: i64 = v?.extract()?;
        if v < 0 {
            return Err(PyValueError::new_err("negative dimensions are not allowed"));
        }
        out_shape.push(v as usize);
    }
    let order1 = order.extract::<i64>()? == 1;
    let cval: f64 = cval.extract()?;
    let out_name: String = if output_dtype.is_none() {
        in_name.extract()?
    } else {
        np.getattr("dtype")?.call1((output_dtype,))?.getattr("name")?.extract()?
    };

    let m_arr: PyReadonlyArrayDyn<'py, f64> = matrix.extract()?;
    let m_view = m_arr.as_array();
    let m: Vec<f64> = (0..n * n).map(|k| m_view[[k / n, k % n]]).collect();
    let o_arr: PyReadonlyArrayDyn<'py, f64> = offset.extract()?;
    let off: Vec<f64> = o_arr.as_array().iter().copied().collect();

    // byte-swapped input: a native copy, as scipy makes
    let arr = if in_dtype.getattr("isnative")?.extract::<bool>()? { arr.clone() } else { arr.call_method1("astype", (&in_name,))? };
    let untyped = arr.cast::<PyUntypedArray>()?;
    let in_shape: Vec<i64> = untyped.shape().iter().map(|&s| s as i64).collect();
    let in_strides: Vec<isize> = untyped.strides().to_vec();
    let src = unsafe { (*untyped.as_array_ptr()).fields.data as *const u8 };
    let job = Job { src: SendPtr(src), in_shape, in_strides, out_shape, m, off, order1, constant, cval };
    let in_name: String = in_name.extract()?;
    let out = out_name.as_str();
    match in_name.as_str() {
        "uint8" => dispatch_out!(py, job, u8, out),
        "uint16" => dispatch_out!(py, job, u16, out),
        "uint32" => dispatch_out!(py, job, u32, out),
        "uint64" => dispatch_out!(py, job, u64, out),
        "int8" => dispatch_out!(py, job, i8, out),
        "int16" => dispatch_out!(py, job, i16, out),
        "int32" => dispatch_out!(py, job, i32, out),
        "int64" => dispatch_out!(py, job, i64, out),
        "float32" => dispatch_out!(py, job, f32, out),
        _ => dispatch_out!(py, job, f64, out),
    }
}

